use core.files as files
use core.process as process

fn find_in(list: [String], target: String) Int -> {
    loop i in 0..list.len() - 1 {
        if list[i] == target -> return i
    }
    return -1
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    text :: files.read(path) ?? panic("read failed")
    raw_lines :: text.lines()

    section_order := [String]{}
    entry_section := [String]{}
    entry_key := [String]{}
    entry_val := [String]{}
    inherits_from := [String]{}
    inherits_to := [String]{}

    current := ""

    loop line in raw_lines {
        trimmed :: ~line.trim()
        if trimmed.is_empty() -> next

        if trimmed.starts_with("[") && trimmed.ends_with("]") {
            current = trimmed.slice(1, trimmed.len() - 2)
            section_order.push(~current)
            next
        }

        if current.is_empty() {
            eprint("error: key outside section")
            process.exit(1)
        }

        parts :: trimmed.split(" = ").to_list()
        if parts.len() < 2 {
            eprint("error: malformed line: {trimmed}")
            process.exit(1)
        }

        key :: ~parts[0]
        raw_val :: ~parts[1]

        val := ~raw_val
        if raw_val.starts_with("\"") && raw_val.ends_with("\"") {
            val = raw_val.slice(1, raw_val.len() - 2)
        }

        if key == "inherits" {
            inherits_from.push(~current)
            inherits_to.push(~val)
            next
        }

        loop j in 0..entry_section.len() - 1 {
            if entry_section[j] == current && entry_key[j] == key {
                eprint("error: duplicate key '{key}' in section '{current}'")
                process.exit(1)
            }
        }

        entry_section.push(~current)
        entry_key.push(~key)
        entry_val.push(~val)
    }

    loop s in 0..section_order.len() - 1 {
        sec :: section_order[s]
        parent_idx :: find_in(inherits_from, sec)
        printed_keys := [String]{}

        if parent_idx >= 0 {
            parent :: inherits_to[parent_idx]
            loop p in 0..entry_key.len() - 1 {
                if entry_section[p] == parent {
                    pk :: entry_key[p]
                    override_idx := -1
                    loop c in 0..entry_key.len() - 1 {
                        if entry_section[c] == sec && entry_key[c] == pk {
                            override_idx = c
                            break
                        }
                    }
                    if override_idx >= 0 -> print("{sec}.{pk}={entry_val[override_idx]}") else -> print("{sec}.{pk}={entry_val[p]}")
                    printed_keys.push(~pk)
                }
            }
        }

        loop e in 0..entry_key.len() - 1 {
            if entry_section[e] == sec {
                ek :: entry_key[e]
                already :: find_in(printed_keys, ek)
                if already < 0 {
                    print("{sec}.{ek}={entry_val[e]}")
                    printed_keys.push(~ek)
                }
            }
        }
    }
}

