use core.process as process

fn find_in(list: [String], target: String) Int -> {
    loop i in 0..list.len() - 1 {
        if list[i] == target -> return i
    }
    return -1
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    text :: files.read(path) ?? panic("read failed")
    raw_lines :: text.lines()

    keys := [String]{}
    vals := [String]{}
    alive := [Bool]{}

    loop line in raw_lines {
        trimmed :: ~line.trim()
        if trimmed.is_empty() -> next

        parts :: trimmed.split("|").to_list()
        if parts.len() < 2 {
            eprint("error: malformed record: {trimmed}")
            process.exit(1)
        }

        kind :: parts[0]
        key :: ~parts[1]

        if {
            kind == "put" -> {
                if parts.len() < 3 {
                    eprint("error: malformed put record: {trimmed}")
                    process.exit(1)
                }
                value :: ~parts[2]
                idx :: find_in(keys, key)
                if {
                    idx >= 0 -> {
                        vals[idx] = ~value
                        alive[idx] = true
                    }
                    else -> {
                        keys.push(~key)
                        vals.push(~value)
                        alive.push(true)
                    }
                }
            }
            kind == "delete" -> {
                idx :: find_in(keys, key)
                if idx >= 0 -> alive[idx] = false
            }
            else -> {
                eprint("error: unknown record kind '{kind}'")
                process.exit(1)
            }
        }
    }

    loop i in 0..keys.len() - 1 {
        if alive[i] -> print("{keys[i]}={vals[i]}")
    }
}","correction_passes":2,"commands":["jet run T3.jet -- journal.log","jet run T3.jet -- journal-failure.log"],"observed":["stdout: beta=2\ngamma=3, exit 0","stderr: error: unknown record kind 'rename', no stdout, exit 1"],"notes":"Replays put/delete journal entries maintaining insertion order. Duplicate put updates value in place. Unknown record kinds exit non-zero."},"T4":{"source":"use core.files as files
use core.process as process

fn json_escape(s: String) String -> {
    result := s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\t", "\\t")
    return result
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    text :: files.read(path) ?? panic("read failed")
    raw_lines :: text.lines()

    name := ""
    count := ""
    note := ""

    loop line in raw_lines {
        trimmed :: ~line.trim()
        if trimmed.is_empty() -> next

        parts :: trimmed.split("\t").to_list()
        if parts.len() < 2 -> next

        key :: parts[0]
        val :: ~parts[1]

        if {
            key == "name" -> name = ~val
            key == "count" -> count = ~val
            key == "note" -> note = ~val
        }
    }

    count_int :: count.to_int() ?? panic("count is not a number")
    escaped_name :: json_escape(name)
    escaped_note :: json_escape(note)

    print("{{\"count\":{count_int},\"name\":\"{escaped_name}\",\"note\":\"{escaped_note}\"}}")
}","correction_passes":1,"commands":["jet run T4.jet -- report.tsv"],"observed":["stdout: {"count":2,"name":"Ada","note":"line \"one\""}, exit 0, exact byte match with trailing newline"],"notes":"Parses TSV key-value pairs, builds typed report, outputs canonical JSON with count/name/note key order and proper escaping."}}
